INSERT INTO public.tests (id,title,description,content,category,specialty_area,status,is_active,specialist_id) VALUES ('de24039c-026a-5531-97e2-ae4349fecc65','Beslenme Hedefleri ve Görüşme Beklentileri Formu','Ön görüşme konusunda diyetisyen görüşmesine hazırlık için özgün, puansız değerlendirme formu.','<p>Özgün ön görüşme formudur; geçerliliği kanıtlanmış klinik ölçek değildir. Yanıt vermek istemediğiniz sorularda paylaşmama seçeneğini kullanabilirsiniz. Sağlık verisi içerebilen yanıtlar mevcut doğrulanmış ayrı izin kapısı açılmadan toplanmaz.</p><p>Yanıtlar yalnız ilgili yetkili diyetisyen tarafından değerlendirilir. Tanı, risk sınıfı veya otomatik beslenme önerisi üretilmez.</p>','Beslenme Değerlendirme Formu','Diyetisyen','pending',false,NULL) ON CONFLICT(id) DO NOTHING;
